INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '1.1', 'DEFINITION', 'Definition of Hospital', 'For HLTH-BASIC, Hospital means a registered institution in India with at least 10 in-patient beds (15 in towns below 10 lakh population), qualified nursing staff round the clock, at least one qualified medical practitioner round the clock, a fully equipped operation theatre and diagnostic facilities of its own. A claim for in-patient Hospitalization is admissible only if treatment was taken in a Hospital so defined; treatment in rest homes, nature-cure clinics or unregistered nursing homes is not payable.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '1.2', 'DEFINITION', 'Definition of Medically Necessary Treatment', 'For HLTH-BASIC, Medically Necessary Treatment means treatment prescribed in writing by a registered medical practitioner, consistent with the diagnosis, consistent with generally accepted Indian medical practice, not primarily for the comfort of the patient, and of a type and duration that can be delivered safely only in a Hospital or Daycare centre. A claim fails if any limb of this definition fails, even if admission exceeded 24 hours.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '1.3', 'DEFINITION', 'Definition of Daycare Procedure', 'For HLTH-BASIC, Daycare Procedure means one of the 140 listed procedures (including cataract phacoemulsification, dialysis, chemotherapy sessions, tonsillectomy and arthroscopy) which owing to medical advancement require hospitalisation of less than 24 hours but more than 2 hours. Ordinary out-patient consultations, injections and diagnostic-only visits are not Daycare Procedures under any cover.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '2.1', 'CONDITION', 'Intimation and cashless pre-authorisation', 'For HLTH-BASIC, every planned admission must be pre-authorised in writing at least 72 hours before admission through a network hospital, and every emergency admission must be intimated to the insurer or TPA within 24 hours of admission. Failure to intimate does not void the claim but attracts a 10 percent reduction of the admissible amount; absence of pre-authorisation means a cashless request may be denied but the claim may still be filed on reimbursement basis.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '2.2', 'CONDITION', 'Claim documentation within 15 days', 'For HLTH-BASIC, the insured must submit the completed claim form, discharge summary, final hospital bill with break-up, prescriptions, investigation reports, pharmacy bills with prescriptions, and cancelled cheque within 15 days of discharge (or within 15 days of completion of OPD treatment for OPD claims). Delayed submission is condonable only with written proof that the delay was beyond the claimant control, and the insurer may reduce the admissible sum by 10 percent for delays beyond 30 days.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '2.3', 'CONDITION', 'Cashless only in network hospitals', 'For HLTH-BASIC, cashless treatment is available only in hospitals empanelled in the insurer network list on the date of admission. Treatment in a non-network hospital is payable strictly on reimbursement basis up to the applicable sub-limit, and the insurer shall not be liable for any denial of admission or advance demanded by a non-network hospital.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '3.1', 'WAITING_PERIOD', '30-day initial waiting period', 'For HLTH-BASIC, no claim for any illness (other than accidental bodily injury requiring hospitalisation) is payable if the date of admission, daycare procedure or OPD consultation falls within 30 days of the first inception of the policy. Accidents, emergency hospitalisation solely due to accident, and renewals without a break are exempt from this waiting period.', 30, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '3.2', 'WAITING_PERIOD', '36-month waiting period for pre-existing diseases', 'For HLTH-BASIC, any hospitalisation, daycare or OPD expense arising from a pre-existing disease (any condition diagnosed or treated in the 48 months before first inception, including disclosed hypertension, diabetes, asthma or thyroid disorders) is payable only after 36 months of continuous cover without break. Disclosure does not shorten this period; non-disclosure voids the claim and the insurer may void the policy under the disclosure condition.', 1095, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'HOSPITALIZATION', '4.1', 'SUB_LIMIT', 'Hospitalization sub-limit Rs 3,00,000', 'For HLTH-BASIC cover HOSPITALIZATION (In-patient Hospitalization), the maximum payable for all in-patient hospitalisation expenses of one insured person in one policy year, including room rent, surgeon and anaesthetist fees, medicines, investigations and 30 days pre- and 60 days post-hospitalisation expenses, is Rs 3,00,000 in aggregate. Any amount above Rs 3,00,000 is borne by the insured even if the base sum insured is higher.', NULL, 300000.00, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'DAYCARE', '4.2', 'SUB_LIMIT', 'Daycare sub-limit Rs 50,000', 'For HLTH-BASIC cover DAYCARE (Daycare Procedures), the maximum payable for all listed daycare procedures of one insured person in one policy year is Rs 50,000 in aggregate, inclusive of procedure charges, medicines and diagnostics on the day of procedure. Hospitalisation exceeding 24 hours for the same ailment is not reclassified as daycare to evade the Hospitalization sub-limit.', NULL, 50000.00, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'OPD', '4.3', 'SUB_LIMIT', 'OPD sub-limit Rs 15,000', 'For HLTH-BASIC cover OPD (Out-patient (OPD)), the maximum payable for all out-patient consultations, prescribed investigations and prescribed medicines in one policy year per insured person is Rs 15,000 in aggregate, with any single consultation capped at Rs 1,500 including prescription charges. Unused OPD balance does not carry forward and cannot be used for in-patient claims.', NULL, 15000.00, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '5.1', 'CO_PAY', '10 percent co-pay above age 60', 'For HLTH-BASIC, every admissible claim for an insured person aged 61 years or above on the date of admission or treatment carries a 10 percent co-pay, meaning the insurer pays 90 percent of the admissible amount after sub-limits and deductibles and the insured bears 10 percent. The co-pay applies separately to each hospitalisation, daycare and OPD bill and does not apply to insured persons aged 60 or below.', NULL, NULL, 10.00, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '6.1', 'EXCLUSION', 'Cosmetic and aesthetic procedures', 'For HLTH-BASIC, no benefit is payable for cosmetic or aesthetic procedures including rhinoplasty, liposuction, hair transplant, mammoplasty, skin whitening or anti-ageing therapy, unless necessitated solely by accidental bodily injury sustained during the policy period and performed within 6 months of the accident with written specialist certification. Reconstructive surgery for burns is payable only under this accident proviso.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '6.2', 'EXCLUSION', 'War, defence service and hazardous pursuits', 'For HLTH-BASIC, treatment of any injury or illness directly caused by war, invasion, rebellion, active defence-service duty, or participation in hazardous pursuits including mountaineering with ropes, professional motor racing, scuba diving below 30 metres, parachuting and underground mining is excluded in all covers. Casual trekking, recreational swimming and amateur marathon running are not hazardous pursuits for this clause.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', NULL, '6.3', 'EXCLUSION', 'AYUSH treatment cap and eligibility', 'For HLTH-BASIC, Ayurveda, Yoga, Unani, Siddha and Homoeopathy (AYUSH) in-patient treatment is payable only when taken in a government-recognised AYUSH hospital with at least 5 beds, and is capped at Rs 20,000 per insured person per policy year across all covers. AYUSH out-patient consultations, herbal supplements bought over the counter, and treatment in wellness spas are not payable.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'HOSPITALIZATION', '7.1', 'EXCLUSION', 'Room rent cap with proportionate deduction', 'For HLTH-BASIC cover HOSPITALIZATION, room rent including boarding and nursing is capped at Rs 5,000 per day or 1 percent of the Hospitalization sub-limit per day, whichever is lower. If the insured occupies a room above this cap, all associated medical charges except pharmacy, consumables and implants shall be reduced in the proportion that the eligible rent bears to the actual rent; ICU charges are capped at Rs 10,000 per day without proportionate deduction.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'HOSPITALIZATION', '7.2', 'EXCLUSION', 'Bariatric surgery threshold', 'For HLTH-BASIC cover HOSPITALIZATION, bariatric or weight-loss surgery including gastric bypass and sleeve gastrectomy is excluded unless the insured has a body mass index of 35 or above with documented obesity-related comorbidity (uncontrolled diabetes, hypertension or sleep apnoea) and the procedure is certified as life-saving by a general surgeon and an endocrinologist after 6 months of failed supervised weight management. The insured must also be aged 18 or above.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'HOSPITALIZATION', '7.3', 'EXCLUSION', 'Joint replacement timing restriction', 'For HLTH-BASIC cover HOSPITALIZATION, knee, hip or shoulder joint replacement is payable only if caused by accidental bodily injury during the policy period, or if performed after 48 months of continuous cover for degenerative arthritis certified by an orthopaedic surgeon with radiological evidence of grade 3 or 4 osteoarthritis. Bilateral replacement in one policy year is capped at one joint even if both knees are affected.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'DAYCARE', '8.1', 'EXCLUSION', 'Diagnostic-only admissions not daycare', 'For HLTH-BASIC cover DAYCARE, hospital attendance solely for diagnostics (MRI, CT scan, endoscopy for evaluation, sleep studies) without a listed therapeutic daycare procedure is not payable as daycare even if the patient occupied a bed for several hours. Such diagnostic expenses may be considered only under the OPD cover within its Rs 15,000 sub-limit and with a specialist referral letter.', NULL, NULL, NULL, '2020-01-01', NULL, 190);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'DAYCARE', '8.2', 'EXCLUSION', 'Minor OPD-manageable procedures', 'For HLTH-BASIC cover DAYCARE, procedures that can ordinarily be completed in under 60 minutes under local anaesthesia in an OPD room (dressings, simple suturing up to 5 stitches, wart or corn removal, nebulisation, routine injections) are excluded from DAYCARE even if done in a hospital, as they do not meet the 2-hour hospitalisation and listed-procedure test in clause 1.3.', NULL, NULL, NULL, '2020-01-01', NULL, 200);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'OPD', '9.1', 'EXCLUSION', 'Vitamins and supplements under OPD', 'For HLTH-BASIC cover OPD, the cost of multivitamins, protein powders, health tonics and nutritional supplements is excluded unless prescribed for a laboratory-confirmed deficiency (for example vitamin D below 20 ng per ml or haemoglobin below 10 g per dl) and taken for a defined course not exceeding 90 days per policy year. General wellness or bodybuilding use is never payable.', NULL, NULL, NULL, '2020-01-01', NULL, 210);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-BASIC', 'OPD', '9.2', 'EXCLUSION', 'Routine dental and vision under OPD', 'For HLTH-BASIC cover OPD, routine dental cleaning, scaling, fillings, root canal, crowns, spectacles, contact lenses and refractive-error correction are excluded. Dental or ophthalmic OPD treatment is payable only where caused solely by accidental bodily injury during the policy period and treated within 30 days of the accident, supported by an emergency record and radiograph.', NULL, NULL, NULL, '2020-01-01', NULL, 220);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '1.1', 'DEFINITION', 'Definition of Hospital and Network Hospital', 'For HLTH-PLUS, Hospital has the same 10-bed (15 in smaller towns), round-the-clock doctor and nurse, operation theatre and diagnostic test as in standard Indian health wordings, and Network Hospital means a Hospital bound by a cashless agreement with the insurer on the date of admission. Only Network Hospitals can offer cashless settlement; all other Hospitals are reimbursed.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '1.2', 'DEFINITION', 'Definition of Pre-existing Disease', 'For HLTH-PLUS, Pre-existing Disease means any condition, ailment, injury or related complication for which the insured had signs or symptoms, diagnosis, or treatment in the 48 months preceding the first inception of continuous cover, as judged from medical records and the proposal form. Hypertension controlled on one tablet and seasonal asthma are pre-existing if documented in that window, even if disclosed.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '1.3', 'DEFINITION', 'Definition of Maternity Expense', 'For HLTH-PLUS, Maternity Expense means medical expenses for delivery (normal or caesarean), lawful medical termination of pregnancy certified to save the life of the mother, and pre-natal and post-natal expenses incurred 30 days before and 60 days after hospitalisation for delivery. Infertility treatment, surrogacy and voluntary termination are not Maternity Expense.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '2.1', 'CONDITION', 'Notification and pre-authorisation windows', 'For HLTH-PLUS, planned admissions require written pre-authorisation at least 72 hours in advance, emergency admissions require intimation within 24 hours, and maternity admissions require intimation within 48 hours of admission. Non-compliance reduces the admissible amount by 10 percent but does not forfeit a genuine claim; cashless denial never bars a reimbursement filing.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '2.2', 'CONDITION', 'Documents and birth certificate for maternity', 'For HLTH-PLUS, all claims need the claim form, discharge summary, itemised final bill, prescriptions with pharmacy bills, and investigation reports within 15 days of discharge; maternity claims additionally need the birth certificate or delivery record and, for caesarean claims, the obstetrician certificate of medical indication. Missing birth proof suspends only the newborn-related portion, not the mother delivery claim.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '2.3', 'CONDITION', 'Disclosure and continuous cover', 'For HLTH-PLUS, the proposer must disclose all pre-existing diseases, prior claims, pregnancies at proposal stage and habitual disclosures honestly; any material non-disclosure allows the insurer to void the claim and cancel the policy from inception with premium forfeited. Waiting periods run only on continuous cover without a break exceeding 30 days; a break resets the maternity and pre-existing clocks.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '3.1', 'WAITING_PERIOD', '36-month wait for pre-existing diseases', 'For HLTH-PLUS, expenses for any pre-existing disease as defined in clause 1.2, including complications such as diabetic nephropathy arising from pre-existing diabetes, are payable only after 1095 days (36 months) of continuous cover. The waiting period applies per insured person and is not shortened by disclosure, higher premium or portability bonus.', 1095, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'MATERNITY', '7.1', 'WAITING_PERIOD', 'Maternity waiting period 270 days (original)', 'For HLTH-PLUS cover MATERNITY, delivery and related maternity expenses were payable only after 270 days of continuous cover from first inception, so a delivery with expected or actual date of delivery within 270 days of inception was excluded. This 270-day rule applied to admissions before 1 April 2024 and is superseded by the revised 180-day rule in the succeeding row of the same clause reference with effect from 1 April 2024.', 270, NULL, NULL, '2020-01-01', '2024-04-01', 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'MATERNITY', '7.1', 'WAITING_PERIOD', 'Maternity waiting period revised to 180 days', 'For HLTH-PLUS cover MATERNITY, with effect from 1 April 2024 this clause supersedes the earlier 270-day rule under the same clause reference 7.1: delivery and related maternity expenses are payable after 180 days of continuous cover from first inception, revised from 270 to 180 days with effect from 1 April 2024. Admissions on or after 1 April 2024 are judged on 180 days; admissions before that date remain judged on 270 days.', 180, NULL, NULL, '2024-04-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'HOSPITALIZATION', '4.1', 'SUB_LIMIT', 'Hospitalization sub-limit Rs 5,00,000', 'For HLTH-PLUS cover HOSPITALIZATION, the maximum payable per insured person per policy year for in-patient expenses including room rent, ICU, surgeon fees, medicines, investigations and 30 days pre- plus 90 days post-hospitalisation is Rs 5,00,000 in aggregate. Room-rent and ICU sub-caps in clauses 8.1 and 9.1 operate within, not in addition to, this Rs 5,00,000.', NULL, 500000.00, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'ROOM_RENT', '4.2', 'SUB_LIMIT', 'Room rent sub-limit Rs 1,00,000', 'For HLTH-PLUS cover ROOM_RENT (Room Rent), the maximum payable per insured person per policy year towards room, boarding and nursing charges is Rs 1,00,000 in aggregate. ICU charges are not counted against this Room Rent sub-limit but against the Hospitalization sub-limit; any room-rent amount above Rs 1,00,000 is borne by the insured.', NULL, 100000.00, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'DAYCARE', '4.3', 'SUB_LIMIT', 'Daycare sub-limit Rs 1,00,000', 'For HLTH-PLUS cover DAYCARE, the maximum payable per insured person per policy year for listed daycare procedures including procedure fees, same-day medicines and diagnostics is Rs 1,00,000 in aggregate. Chemotherapy and dialysis sessions each count separately against this sub-limit per session date.', NULL, 100000.00, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'OPD', '4.4', 'SUB_LIMIT', 'OPD sub-limit Rs 30,000', 'For HLTH-PLUS cover OPD, the maximum payable per insured person per policy year for consultations, prescribed diagnostics and prescribed medicines is Rs 30,000 in aggregate, capped at Rs 2,000 per consultation including prescribed drugs for that visit. Preventive health check-ups up to Rs 2,000 per year are included within this Rs 30,000 and require no illness trigger.', NULL, 30000.00, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'MATERNITY', '4.5', 'SUB_LIMIT', 'Maternity sub-limit Rs 75,000', 'For HLTH-PLUS cover MATERNITY (Maternity), the maximum payable per insured person per policy year for delivery (normal delivery capped at Rs 50,000 and caesarean delivery capped at Rs 75,000 within the aggregate), 30 days pre-natal and 60 days post-natal expenses, and newborn cover for the first 30 days is Rs 75,000 in aggregate. Twin deliveries in one confinement count as one event against this sub-limit.', NULL, 75000.00, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '5.1', 'CO_PAY', '20 percent co-pay on reimbursement claims', 'For HLTH-PLUS, every admissible claim filed on reimbursement basis (treatment in a non-network hospital) carries a 20 percent co-pay: the insurer pays 80 percent of the admissible amount after sub-limits and the insured bears 20 percent. Cashless claims in network hospitals carry no co-pay under this clause; the maternity and OPD covers follow the same reimbursement co-pay rule.', NULL, NULL, 20.00, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '6.1', 'EXCLUSION', 'Cosmetic surgery unless after accident', 'For HLTH-PLUS, cosmetic, aesthetic or plastic surgery including liposuction, rhinoplasty, breast augmentation or reduction, hair restoration and anti-ageing therapies is excluded in all covers unless certified as reconstructive treatment for accidental bodily injury or burns sustained during the policy period and performed within 6 months of the event. Surgery for congenital anomaly without functional impairment remains excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '6.2', 'EXCLUSION', 'Self-harm, substance abuse and HIV', 'For HLTH-PLUS, treatment for intentional self-injury or attempted suicide, any illness or injury attributable to alcohol, narcotics or psychotropic substance abuse, and HIV or AIDS with related opportunistic conditions is excluded in all covers. Accidental injury to a person with controlled HIV is payable for the accident itself, but antiretroviral therapy remains excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '6.3', 'EXCLUSION', 'War, nuclear and hazardous sports', 'For HLTH-PLUS, injury or illness caused by war, civil commotion, nuclear reaction or radiation, active military or paramilitary duty, or hazardous pursuits (car or bike racing, mountaineering, deep-sea diving, paragliding, bungee jumping, professional contact sports) is excluded. Commuting accidents and amateur recreational sports without remuneration are not excluded under this clause.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', NULL, '6.4', 'EXCLUSION', 'AYUSH eligibility and annual cap', 'For HLTH-PLUS, AYUSH in-patient treatment is payable only in a government-recognised AYUSH hospital and is capped at Rs 25,000 per insured person per policy year across all covers; AYUSH OPD consultations are counted within the OPD Rs 30,000 sub-limit. Massages, spa therapies and over-the-counter herbal products without an AYUSH practitioner prescription are never payable.', NULL, NULL, NULL, '2020-01-01', NULL, 190);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'HOSPITALIZATION', '8.1', 'EXCLUSION', 'Single private room upgrade consequence', 'For HLTH-PLUS cover HOSPITALIZATION, if the insured chooses a single private air-conditioned room where the hospital also offers eligible shared accommodation, room rent above Rs 8,000 per day is disallowed and associated procedure and surgeon charges are scaled down proportionately to the ratio of Rs 8,000 to actual room rent, excluding pharmacy, consumables and implants. ICU stays and hospitals with only private rooms are exempt from this proportionate deduction.', NULL, NULL, NULL, '2020-01-01', NULL, 200);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'HOSPITALIZATION', '8.2', 'EXCLUSION', 'Obesity and bariatric surgery bar', 'For HLTH-PLUS cover HOSPITALIZATION, treatment for obesity and bariatric surgery is excluded unless body mass index is 35 or above with documented comorbidity, the insured is 18 or above, and 6 months of supervised non-surgical management has failed with specialist certification. Diet counselling alone for weight loss is never payable.', NULL, NULL, NULL, '2020-01-01', NULL, 210);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'HOSPITALIZATION', '8.3', 'EXCLUSION', 'Specified procedures two-year wait', 'For HLTH-PLUS cover HOSPITALIZATION, cataract, hernia, hydrocele, piles, fissure, sinusitis surgery, benign uterine surgery and spinal disorders are payable only after 24 months of continuous cover, unless caused solely by accident during the policy period. OPD consultations for these conditions before 24 months remain payable within the OPD sub-limit.', NULL, NULL, NULL, '2020-01-01', NULL, 220);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'ROOM_RENT', '9.1', 'EXCLUSION', 'ICU daily cap under room rent claims', 'For HLTH-PLUS cover ROOM_RENT, intensive care unit charges above Rs 12,000 per day per insured person are disallowed and borne by the insured, while general room rent above Rs 8,000 per day is disallowed under clause 8.1 with proportionate deduction. Ventilator and monitor charges bundled into ICU billing above the cap are disallowed in the same proportion.', NULL, NULL, NULL, '2020-01-01', NULL, 230);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'ROOM_RENT', '9.2', 'EXCLUSION', 'Attendant food and luxury services', 'For HLTH-PLUS cover ROOM_RENT, food and stay charges of attendants, telephone, television, mineral water, luxury toiletries, admission kit and service charges levied as a percentage of the bill are excluded even within the Rs 1,00,000 Room Rent sub-limit. Only the patient room, boarding and nursing charges evidenced in the itemised bill are admissible.', NULL, NULL, NULL, '2020-01-01', NULL, 240);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'DAYCARE', '10.1', 'EXCLUSION', 'Diagnostics-only day attendance', 'For HLTH-PLUS cover DAYCARE, attendance solely for MRI, CT, PET scan, endoscopy for diagnosis, or dialysis adequacy tests without a therapeutic listed daycare procedure is excluded from DAYCARE. Such diagnostic costs are admissible only under OPD within Rs 30,000 with a specialist referral, not under the Rs 1,00,000 daycare sub-limit.', NULL, NULL, NULL, '2020-01-01', NULL, 250);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'DAYCARE', '10.2', 'EXCLUSION', 'OPD-manageable minor procedures', 'For HLTH-PLUS cover DAYCARE, laceration dressings, simple excisions under local anaesthesia completed within 60 minutes, ear syringing, nebulisation and routine vaccinations are excluded from DAYCARE even if billed as daycare, because they fail the listed-procedure and 2-hour hospitalisation test. They may be claimed under OPD if prescribed.', NULL, NULL, NULL, '2020-01-01', NULL, 260);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'OPD', '11.1', 'EXCLUSION', 'Spectacles, dental and hearing aids', 'For HLTH-PLUS cover OPD, spectacles, contact lenses, hearing aids, routine dental cleaning, fillings, crowns, implants and orthodontics are excluded. Dental or eye treatment under OPD is payable only for accidental bodily injury during the policy period treated within 30 days with emergency and radiology proof, capped within the Rs 30,000 OPD sub-limit.', NULL, NULL, NULL, '2020-01-01', NULL, 270);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'OPD', '11.2', 'EXCLUSION', 'Supplements and non-prescribed tonics', 'For HLTH-PLUS cover OPD, protein supplements, multivitamins, ayurvedic tonics and health drinks are excluded unless prescribed for a laboratory-confirmed deficiency for a course up to 90 days per year. Over-the-counter purchases without a registered practitioner prescription are never payable even within the OPD sub-limit.', NULL, NULL, NULL, '2020-01-01', NULL, 280);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'MATERNITY', '12.1', 'EXCLUSION', 'Voluntary termination exclusion', 'For HLTH-PLUS cover MATERNITY, voluntary medical termination of pregnancy is excluded unless certified in writing by two registered practitioners as necessary to save the life of the mother or to prevent grave permanent injury to her physical health. Elective termination for family planning, gender selection (which is separately unlawful) or social reasons is never payable.', NULL, NULL, NULL, '2020-01-01', NULL, 290);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-PLUS', 'MATERNITY', '12.2', 'EXCLUSION', 'Infertility and surrogacy bar', 'For HLTH-PLUS cover MATERNITY, all infertility work-up and treatment including ovulation induction, intra-uterine insemination, in-vitro fertilisation, intracytoplasmic sperm injection, surrogacy charges, gamete donation and storage of embryos is excluded from the Rs 75,000 maternity sub-limit. A resulting pregnancy once confirmed is covered for delivery subject to the 180-day (earlier 270-day) waiting rule and sub-limit.', NULL, NULL, NULL, '2020-01-01', NULL, 300);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '1.1', 'DEFINITION', 'Definition of Critical Illness event', 'For HLTH-CRIT, Critical Illness means one of the 32 listed conditions (including invasive cancer, myocardial infarction with troponin rise and ECG change, open-chest coronary bypass, major-organ transplant, kidney failure on regular dialysis, stroke with 3-month neurological deficit, and multiple sclerosis with persistent deficit) first diagnosed during the policy period and certified by a specialist with histology or imaging proof. Pre-malignant, in-situ and low-grade prostate cancers are not Critical Illness.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '1.2', 'DEFINITION', 'Survival period and confirmation', 'For HLTH-CRIT, the Critical Illness lump sum is payable only if the insured survives 30 days from the date of confirmed diagnosis or surgery, and the diagnosis is confirmed by Indian specialist evidence (for example biopsy for cancer, angiography for bypass, MRI for stroke). Death within 30 days converts the claim to a Hospitalization claim only, not the lump sum.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '1.3', 'DEFINITION', 'Definition of Pre-existing Disease', 'For HLTH-CRIT, Pre-existing Disease has the standard 48-month look-back meaning: any condition with signs, symptoms, diagnosis or treatment in the 48 months before first inception, including hypertension, diabetes, prior angina or prior tumour. A disclosed and accepted pre-existing condition remains subject to the 1095-day waiting period in clause 3.2.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '2.1', 'CONDITION', 'Specialist certification and records', 'For HLTH-CRIT, every Critical Illness claim needs a specialist certificate stating the listed condition, date of first diagnosis, histology or imaging proof, prior history, and survival of 30 days, plus hospital records, discharge summary and investigation films. The insurer may require an independent medical examination at its cost; refusal voids the lump-sum assessment.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '2.2', 'CONDITION', 'One-time lump sum and policy termination', 'For HLTH-CRIT, the Critical Illness benefit is a one-time lump sum per insured person for the first qualifying event; payment of the lump sum terminates the Critical Illness cover for that person while the Hospitalization cover (Rs 5,00,000) continues for unrelated ailments. A second critical illness of any type is not payable after the lump sum is paid.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '2.3', 'CONDITION', 'Intimation and filing deadline', 'For HLTH-CRIT, the insurer or TPA must be intimated within 15 days of diagnosis or surgery, and the completed claim with all proof must be filed within 60 days of diagnosis. Delay is condonable only with hospital-certified reasons; cashless facility is not available for the lump sum, which is always paid by account transfer after verification.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '3.1', 'WAITING_PERIOD', '90-day initial wait for critical illness', 'For HLTH-CRIT, no Critical Illness lump sum is payable if the first diagnosis or surgery date of the listed illness falls within 90 days of first inception. Hospitalization claims for accidents during these 90 days remain payable under the Hospitalization cover; renewal without break is exempt from a fresh 90-day wait.', 90, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '3.2', 'WAITING_PERIOD', '36-month wait for pre-existing critical illness', 'For HLTH-CRIT, any Critical Illness substantially attributable to a pre-existing disease (for example bypass surgery where coronary disease was documented in the 48 months before inception) is payable only after 1095 days of continuous cover. The treating cardiologist or oncologist must certify whether the event is linked to prior history; disputes are referred to an independent specialist.', 1095, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'CRITICAL_ILLNESS', '4.1', 'SUB_LIMIT', 'Critical illness lump sum Rs 25,00,000', 'For HLTH-CRIT cover CRITICAL_ILLNESS (Critical Illness (lump sum)), the benefit is a fixed lump sum of Rs 25,00,000 per insured person for the first qualifying listed illness meeting definitions and waiting periods, irrespective of actual hospital expenditure. No deductions for prior Hospitalization claims apply, but the lump sum extinguishes further Critical Illness benefit for that person.', NULL, 2500000.00, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'HOSPITALIZATION', '4.2', 'SUB_LIMIT', 'Hospitalization sub-limit Rs 5,00,000', 'For HLTH-CRIT cover HOSPITALIZATION, the maximum payable per insured person per policy year for in-patient treatment including pre- and post-hospitalisation for 30 and 60 days respectively is Rs 5,00,000 in aggregate. Hospital bills for the critical-illness event itself are counted within this Rs 5,00,000 separately from the Rs 25,00,000 lump sum.', NULL, 500000.00, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '5.1', 'CO_PAY', '10 percent co-pay on hospitalization', 'For HLTH-CRIT, every admissible Hospitalization claim carries a 10 percent co-pay (insurer pays 90 percent after sub-limits) irrespective of hospital network status. The Critical Illness lump sum of Rs 25,00,000 carries no co-pay and is paid in full when admissible.', NULL, NULL, 10.00, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '6.1', 'EXCLUSION', 'Lifestyle and congenital exclusions', 'For HLTH-CRIT, critical illnesses or hospitalisation caused by alcohol, drug abuse, intentional self-injury, participation in hazardous sports, or congenital external anomalies are excluded in all covers. A road accident injury to a person with alcohol dependence is payable only with proof that blood alcohol was within the legal driving limit at the time of accident.', NULL, NULL, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '6.2', 'EXCLUSION', 'Cosmetic and obesity exclusion', 'For HLTH-CRIT, cosmetic, aesthetic, bariatric and infertility-related treatments are excluded from all covers, including hospitalisation following such procedures, unless reconstructive surgery is required within 6 months of accidental bodily injury during the policy period. Bariatric surgery meeting the BMI-35 with comorbidity test remains excluded from the lump sum but may be considered under Hospitalization only after 48 months.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', NULL, '6.3', 'EXCLUSION', 'War, nuclear and defence duty', 'For HLTH-CRIT, any critical illness diagnosis or hospitalisation caused by war, rebellion, nuclear contamination, chemical or biological weapons, or active defence or paramilitary duty is excluded. Cancers attributable solely to documented occupational radiation within permissible limits are judged on medical evidence and are not automatically excluded under this clause.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'CRITICAL_ILLNESS', '7.1', 'EXCLUSION', 'Early-stage cancers excluded', 'For HLTH-CRIT cover CRITICAL_ILLNESS, carcinoma in situ, cervical dysplasia CIN-1 to CIN-3, prostate cancer below Gleason 7 or T2N0M0, papillary thyroid microcarcinoma below 1 cm, non-melanoma skin cancer without metastasis, and monoclonal gammopathy are excluded from the lump sum. Only histologically confirmed invasive malignancy with uncontrolled growth and spread is qualifying.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'CRITICAL_ILLNESS', '7.2', 'EXCLUSION', 'Angioplasty and minor cardiac procedures', 'For HLTH-CRIT cover CRITICAL_ILLNESS, coronary angioplasty (balloon or stent), pacemaker implantation, implantable defibrillator without sustained ventricular arrhythmia, and valve repair without open-chest surgery do not qualify for the lump sum; only open-chest coronary artery bypass grafting, major valve replacement by open-heart surgery, or myocardial infarction meeting troponin plus ECG criteria qualify.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'CRITICAL_ILLNESS', '7.3', 'EXCLUSION', 'Transient neurological events', 'For HLTH-CRIT cover CRITICAL_ILLNESS, transient ischaemic attacks, migraine with aura, Bell palsy, epilepsy without structural brain lesion, and head injury without 3-month persistent deficit are excluded from the lump sum. Stroke qualifies only with fresh imaging proof and permanent neurological deficit persisting 3 months and certified by a neurologist.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'HOSPITALIZATION', '8.1', 'EXCLUSION', 'Diagnostics-only admission', 'For HLTH-CRIT cover HOSPITALIZATION, admission solely for MRI, CT, PET scan, endoscopy, sleep study or pre-employment screening without active therapeutic treatment requiring more than 24 hours stay is excluded. Such costs are not payable under Hospitalization even within Rs 5,00,000; they need a distinct OPD-type benefit which this product does not offer.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-CRIT', 'HOSPITALIZATION', '8.2', 'EXCLUSION', 'Room upgrade proportionate deduction', 'For HLTH-CRIT cover HOSPITALIZATION, room rent above Rs 7,500 per day triggers proportionate reduction of associated surgeon, anaesthetist and procedure charges in the ratio of Rs 7,500 to actual rent, excluding pharmacy, consumables and implants. ICU charges above Rs 12,000 per day are disallowed in full excess; hospitals with no lower-category room are exempt on written proof.', NULL, NULL, NULL, '2020-01-01', NULL, 190);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-ORPHAN', NULL, '6.1', 'EXCLUSION', 'Experimental and unproven treatment', 'For HLTH-ORPHAN, any treatment that is experimental, unproven or not recognised by the Medical Council of India or Indian Council of Medical Research protocols on the date of treatment, including stem-cell therapy outside approved haematological indications, gene therapy and unapproved immunotherapies, is excluded. Participation in a registered clinical trial is excluded even if the hospital charges routine care separately.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-ORPHAN', NULL, '2.1', 'CONDITION', 'Fraud and disclosure condition', 'For HLTH-ORPHAN, if any claim is fraudulent, or if the proposer has concealed a material medical fact that would have affected underwriting, the insurer may void the claim and cancel the cover from inception with forfeiture of premium. The burden of proving non-materiality lies on the insured, and proven fraud bars any further claim under the product.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HLTH-ORPHAN', NULL, '1.1', 'DEFINITION', 'Definition of Medical Practitioner', 'For HLTH-ORPHAN, Medical Practitioner means a person holding a recognised medical qualification registered with the Medical Council of India or a State Medical Council, acting within licence scope, and excluding the insured person, spouse, parent or child of the insured. A prescription or certificate from a non-registered practitioner cannot ground any claim under this product.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'D-1', 'DEFINITION', 'Insured''s Declared Value (IDV)', 'IDV is the sum insured for Own Damage fixed at policy inception from the manufacturer''s ex-showroom price of the same make, model and variant less depreciation per the age slab in clause D-2, plus the declared value of factory-fitted or declared accessories. IDV is the maximum payable for total loss, constructive total loss or theft of the entire vehicle, less compulsory excess of INR 1,000 and any depreciation or deductions stated elsewhere. IDV is not the market or resale value on the date of loss and is not revised mid-term except for a declared accessory endorsement.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'D-2', 'DEFINITION', 'Depreciation schedule for partial-loss assessment', 'For partial-loss repairs: all rubber, nylon and plastic parts including tyres, tubes and battery 50 percent; fibre-glass components 30 percent; all parts made of glass nil; painting material 25 percent in the first year of registration. On other parts including metal panels: nil where vehicle age does not exceed 6 months, 5 percent where age exceeds 6 months but not 1 year, 10 percent for 1 to 2 years, 15 percent for 2 to 3 years, 25 percent for 3 to 4 years, 35 percent for 4 to 5 years, 40 percent for 5 to 10 years, and 50 percent above 10 years, age counted from first registration to date of accident. Labour charges attract no depreciation.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'D-3', 'DEFINITION', 'No Claim Bonus (NCB)', 'NCB is a discount on the Own Damage premium only, earned after each claim-free policy year with the same owner: 20 percent after one year, 25 percent after two years, 35 percent after three years, 45 percent after four years, 50 percent after five or more years. Any Own Damage claim in the expiring year resets NCB to nil at next renewal. NCB belongs to the owner, not the vehicle, and may transfer to a replacement vehicle within 3 years on production of the prior NCB reserving letter. Third-party premium never earns NCB.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', 'OWN_DAMAGE', 'S-1', 'SUB_LIMIT', 'Own Damage aggregate limit INR 30,000', 'The maximum payable under the Own Damage cover for all accidents in one policy period is INR 30,000 in aggregate, inclusive of parts after depreciation per clause D-2, labour, towing up to INR 1,500 per event, and survey fee. Compulsory excess of INR 1,000 per event applies within this limit. Any amount above INR 30,000 is borne by the insured. This limit does not reduce IDV for the purpose of a later total-loss claim, which remains capped separately at IDV.', NULL, 30000.00, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'E-1', 'EXCLUSION', 'Drink-and-drive and drug-use exclusion', 'No claim is payable for any loss occurring while the driver was under the influence of alcohol above 30 mg per 100 ml of blood or any narcotic or psychotropic substance, established by breath analyser, blood or urine report, hospital record, or a police charge sheet under Section 185 of the Motor Vehicles Act 1988. Refusal to undergo a lawfully demanded test after an accident is treated as a breach of this clause. This exclusion applies to every cover of this product.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'E-2', 'EXCLUSION', 'No effective driving licence exclusion', 'No claim is payable where at the time of accident the driver held no effective driving licence for the class of vehicle insured, or the licence had expired more than 30 days earlier, was suspended, or was for a different class such as a two-wheeler licence used for a private car. A learner''s licence is effective only when the learner is accompanied in the front passenger seat by a person holding an effective licence for that class for at least 3 years and the vehicle displays L plates front and rear. This exclusion applies to every cover of this product.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'E-3', 'EXCLUSION', 'Use outside India', 'No claim is payable for loss arising outside the geographical area of India. Transit of the insured vehicle by road, rail or inland waterway between points in India remains covered while the vehicle is carried as cargo and not driven under its own power. Any accident in Nepal, Bhutan or any other neighbouring territory is excluded even if the journey originated in India.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'E-4', 'EXCLUSION', 'Hire, racing and testing exclusion', 'No claim is payable where the private car was at the time of loss used for hire or reward including taxi or rental use without a commercial endorsement, or for racing, pace-making, speed testing, reliability trials or rallies. Normal commuting and a registered car pool sharing fuel cost without profit are not hire. This exclusion applies to every cover of this product.', NULL, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', 'OWN_DAMAGE', '4.2', 'EXCLUSION', 'Consequential engine loss including hydrostatic lock', 'Own Damage covers engine damage directly caused by the insured accident such as impact or initial water entry during floods, but excludes consequential damage from continued use afterwards. In particular, where water has entered the engine or the vehicle has stalled in flood water, any seizure, bending of connecting rods or hydrostatic lock caused by cranking, push-starting or restarting the engine is excluded; the insured must stop, switch off and call for towing. The cost of the initial impact or water-entry repair remains payable subject to depreciation, while the consequential engine rebuild, typically INR 40,000 to INR 150,000, is not.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', 'OWN_DAMAGE', '4.3', 'EXCLUSION', 'Wear and tear, breakdown and depreciation', 'Own Damage does not cover wear and tear, gradual deterioration, rust, or mechanical or electrical breakdown or failure of any part unconnected with an insured accident, including a timing-belt snap, clutch-plate wear or battery discharge through ageing. Tyre and tube damage is excluded unless the vehicle suffers simultaneous damage to another insured part in the same accident, in which case 50 percent depreciation under clause D-2 still applies to the tyre claim. Depreciation amounts computed under clause D-2 are themselves excluded from every payment.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', 'OWN_DAMAGE', '4.4', 'EXCLUSION', 'War, nuclear and government requisition', 'Own Damage does not cover loss directly caused by war, invasion, act of foreign enemy, hostilities whether declared or not, civil war, mutiny, rebellion, revolution, military or usurped power, ionising radiation or contamination by radioactivity from any nuclear fuel or waste, or requisition, seizure or destruction by or under order of any government or public authority. A riot, strike or malicious act unconnected with war remains covered as an insured peril and is not excluded by this clause.', NULL, NULL, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'C-1', 'CONDITION', 'Notice of loss and police reporting', 'The insured must give written notice of any accident, theft or third-party claim within 48 hours of occurrence and a detailed written claim within 7 days, and must take all reasonable steps to protect the vehicle from further loss including towing rather than driving a damaged vehicle. Any accident involving third-party death or bodily injury, theft or rioting must additionally be reported to the police within 24 hours under Section 134 of the Motor Vehicles Act 1988 and a copy of the FIR or community service copy produced. Delay beyond these windows is condoned only where the insured proves it was not reasonably practicable and no prejudice was caused.', NULL, NULL, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'C-2', 'CONDITION', 'Documents for Own Damage and theft claims', 'Every Own Damage claim must be supported by the registration certificate (RC), the driver''s effective licence for the vehicle class, repair bills with parts and labour split, and for theft the original keys, FIR and the final untraced report. Where the RC is hypothecated to a bank, the claim up to INR 30,000 is paid to the insured after a no-objection from the hypothecatee; total-loss payment is made jointly to insured and hypothecatee. Failure to produce any document within 30 days of demand allows the insurer to close the file as no-claim unless the document is shown to be unavailable for reasons beyond control.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO', NULL, 'C-3', 'CONDITION', 'Cashless garage, survey and salvage', 'Cashless repair is available only at network garages after pre-authorisation and a spot or final survey; repairs begun before survey without insurer consent are reimbursed only up to the surveyor''s assessed prevailing labour rates for that city. The insured must preserve damaged parts for inspection. On payment of a total loss or theft claim at IDV, the wreck or recovered vehicle and its RC transfer become the insurer''s salvage, and the insured must execute transfer forms and hand over both keys within 15 days of payment.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'D-1', 'DEFINITION', 'Insured''s Declared Value (IDV)', 'IDV is the sum insured for Own Damage agreed at inception from the ex-showroom price of the same make, model, variant and fuel type less depreciation per clause D-2, plus declared electrical, electronic and CNG or LPG kit values. IDV caps any total loss, constructive total loss where repair exceeds 75 percent of IDV, or theft settlement, less compulsory excess of INR 2,000 for private cars above 1500 cc and INR 1,000 otherwise. IDV is fixed for the policy year and is not the market value at loss.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'D-2', 'DEFINITION', 'Depreciation schedule for partial-loss assessment', 'For partial-loss assessment: all rubber, nylon and plastic parts including tyres, tubes, batteries and airbags covers 50 percent; fibre-glass components 30 percent; all parts made of glass nil; painting material 25 percent where vehicle age is below 5 years and 30 percent thereafter. On metal and other parts: nil up to 6 months from first registration, 5 percent for 6 months to 1 year, 10 percent for 1 to 2 years, 15 percent for 2 to 3 years, 25 percent for 3 to 4 years, 35 percent for 4 to 5 years, 40 percent for 5 to 10 years, 50 percent above 10 years. Labour is paid in full without depreciation.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'D-3', 'DEFINITION', 'Third-party liability scope', 'Third-party liability means legal liability for death of or bodily injury to any person who is not an occupant of the insured vehicle and is not the insured or driver, plus damage to property not owned by or in the custody of the insured, arising from use of the insured vehicle in a public place. A pillion passenger on a two-wheeler or an occupant of a private car is not a third party under this cover unless a separate personal accident or occupant endorsement applies. The insurer''s liability for third-party property damage is capped at the sub-limit in clause S-2; death and bodily injury liability is unlimited in amount but decided by Indian courts or Motor Accident Claims Tribunals only.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'OWN_DAMAGE', 'S-1', 'SUB_LIMIT', 'Own Damage aggregate limit INR 500,000', 'The maximum payable under Own Damage for all events in one policy period is INR 500,000 in aggregate, inclusive of parts after depreciation per clause D-2, labour, towing up to INR 3,000 per event and survey charges. Compulsory excess per event applies within this limit. Any excess over INR 500,000 is borne by the insured. Total-loss or theft settlement within this limit is additionally capped at IDV.', NULL, 500000.00, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'THIRD_PARTY', 'S-2', 'SUB_LIMIT', 'Third-party property damage limit INR 750,000', 'The maximum payable for third-party property damage under the Third-party Liability cover is INR 750,000 per policy period in aggregate, inclusive of assessed repair cost of third-party property, towing of the third-party vehicle and claimant costs awarded by a court or Tribunal. Each third-party property claim bears no compulsory excess under this standard product. Liability for third-party death or bodily injury is not subject to this sub-limit and is indemnified as awarded by a competent Indian court or Tribunal.', NULL, 750000.00, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'W-1', 'WAITING_PERIOD', 'Seven-day theft waiting window on fresh cover after a break', 'Where this policy is issued as fresh cover after a break in insurance exceeding 30 days, theft of the entire insured vehicle occurring within the first 7 days from the risk start date and time printed on the schedule is not payable. This waiting window applies only to theft of the whole vehicle, not to partial theft of accessories, accident damage, or any third-party liability. Continuous renewals without a break, and rollover within 30 days of expiry supported by the prior policy, are not subject to this window.', 7, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'E-1', 'EXCLUSION', 'Drink-and-drive and drug-use exclusion', 'No claim under any cover of this product is payable for loss occurring while the driver was under the influence of alcohol exceeding 30 mg per 100 ml of blood or any narcotic substance, evidenced by breath, blood or urine test, casualty papers, or conviction or charge under Section 185 of the Motor Vehicles Act 1988. Refusal of a lawfully required test at the scene is treated as breach. A passenger''s intoxication alone does not trigger this exclusion where the driver was sober.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'E-2', 'EXCLUSION', 'No effective driving licence exclusion', 'No claim under any cover is payable where the driver at the time of accident held no effective licence for the class of vehicle, the licence had expired more than 30 days before, or it was suspended or issued for a different class, for example a non-transport licence used for a transport vehicle. A learner''s licence counts only with L plates displayed and a qualified companion holding that class licence for at least 3 years seated beside the driver. A driving licence valid on the date of accident but produced late still satisfies this clause if produced within 15 days of demand.', NULL, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'E-3', 'EXCLUSION', 'Territorial exclusion outside India', 'No claim under any cover is payable for an accident, loss or liability arising outside India. Carriage of the insured vehicle by road, rail, inland waterway or coastal shipment between Indian ports remains covered while not driven under its own power. Awards of foreign courts and liabilities under foreign motor statutes are excluded; only awards of Indian courts and Motor Accident Claims Tribunals under the Motor Vehicles Act 1988 are indemnified.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'E-4', 'EXCLUSION', 'Hire, racing and testing exclusion', 'No claim under any cover is payable while the vehicle was used for hire or reward without the proper commercial endorsement, for carriage of goods beyond the registered laden weight, or for racing, pace-making, speed testing, reliability trials or motor rallies and practice therefor. Private car-pooling sharing fuel costs without profit, and use for commuting to a fixed workplace, are not hire for this clause.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'OWN_DAMAGE', 'O-1', 'EXCLUSION', 'Consequential engine loss including hydrostatic lock', 'Own Damage pays for engine damage directly caused by an insured peril such as collision impact or first ingress of flood water, but not for aggravation through continued operation. If the engine stalls in waterlogging, any piston, connecting-rod or valve damage from attempting to crank, push-start or restart is excluded as consequential hydrostatic lock; the correct step is to switch off and tow to a garage. The admissible claim is limited to flushing, drying and directly damaged parts assessed before the restart attempt, typically a few thousand rupees, while a full engine rebuild of INR 50,000 to INR 200,000 after cranking is excluded. Zero-depreciation-style full replacement of the engine is not available under this standard product.', NULL, NULL, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'OWN_DAMAGE', 'O-2', 'EXCLUSION', 'Wear and tear, breakdown and tyre-only loss', 'Own Damage excludes wear and tear, corrosion, and mechanical or electrical breakdown not traceable to an insured accident in the same event, such as gearbox failure from worn synchromesh or ECU failure from ageing. Loss confined to tyres, tubes or battery without simultaneous insured damage to another part of the vehicle is excluded; where simultaneous damage exists, tyres and battery are paid only after 50 percent depreciation. Betterment from replacing an old part with a new one, and the depreciation slice itself, are excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'OWN_DAMAGE', 'O-3', 'EXCLUSION', 'War, nuclear, requisition and wilful neglect', 'Own Damage excludes loss caused by war, invasion, civil war, rebellion, revolution, military or usurped power, ionising radiation or nuclear contamination, and requisition or destruction by government order. It also excludes loss caused by wilful neglect such as leaving the vehicle unlocked with the engine running or keys in the ignition in a public place leading to theft, or driving into a visibly flooded underpass against police barricades. Riot, strike, malicious act and flood without such neglect remain covered.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'THIRD_PARTY', 'T-1', 'EXCLUSION', 'Own damage and occupant injury not covered as third party', 'The Third-party Liability cover does not pay for damage to the insured vehicle itself, injury to the insured or the driver in charge, or injury to any occupant carried in or on the insured private car, whether family, friend or fare-paying passenger. Such persons must claim under Own Damage, personal accident or occupant endorsements where purchased. Only persons outside the insured vehicle, occupants of other vehicles, and pedestrians qualify as third parties here.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', 'THIRD_PARTY', 'T-2', 'EXCLUSION', 'Contractual liability, fines and exemplary damages', 'The Third-party Liability cover indemnifies only statutory liability under the Motor Vehicles Act 1988 as awarded by an Indian court or Tribunal. Liability assumed by contract beyond statute, fines and compounding fees under Sections 177 to 210 of the Act, and exemplary or punitive damages are excluded. Interest awarded by a Tribunal from the date of filing is payable within policy limits, but interest arising from the insured''s delay in notifying the insurer under clause C-1 beyond 30 days is excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'C-1', 'CONDITION', 'Notice, police report and cooperation', 'Written notice of any accident, theft or third-party summons must reach the insurer within 48 hours, with claim form and photographs within 7 days. Third-party injury, death, theft and riot losses must be reported to police within 24 hours under Section 134 of the Motor Vehicles Act 1988. The insured must forward every summons, notice and correspondence unanswered, attend Tribunal hearings as required, and must not admit liability, settle or promise payment without written insurer consent, failing which the third-party claim may be defended at the insured''s cost.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'C-2', 'CONDITION', 'Documents: RC, licence, FIR and bills', 'Own Damage claims require RC, effective driving licence for the vehicle class, repair estimate and final bills with parts-labour split, and survey report. Theft claims additionally require both keys, FIR, final untraced report, and a subrogation and transfer letter. Third-party claims require the FIR, spot survey or motor collision report, driving licence, insurance certificate, and Tribunal summons. Documents must be filed within 30 days of demand; the file may be closed as no-claim for non-compliance after two reminders.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-STD', NULL, 'C-3', 'CONDITION', 'Cashless repairs, survey and salvage', 'Cashless settlement is available only at network garages with prior authorisation and surveyor approval of the estimate; the insured bears any betterment, depreciation and non-affiliated consumables. Non-network repairs are reimbursed at the surveyor-assessed reasonable rates for that city after a final survey. Damaged parts must be preserved. On total loss, constructive total loss or theft settlement, salvage and the right to the wreck or recovered vehicle vest in the insurer, and the insured must sign transfer deeds and surrender keys and RC within 15 days.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'D-1', 'DEFINITION', 'Insured''s Declared Value (IDV)', 'IDV is the Own Damage sum insured fixed at inception from the latest ex-showroom price of the same make, model, variant and cubic capacity less depreciation per clause D-2, plus declared values of CNG or LPG kits, alloy wheels and other declared accessories with bills. IDV is the ceiling for total loss, constructive total loss where estimated repairs exceed 75 percent of IDV, and theft of the entire vehicle, less compulsory excess of INR 2,000. Mid-term IDV revision is allowed only by endorsement for a new accessory or change of hypothecation.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'D-2', 'DEFINITION', 'Depreciation schedule and betterment', 'Partial-loss parts depreciation: rubber, nylon, plastic, tyres, tubes and batteries 50 percent; fibre-glass 30 percent; glass parts nil; painting material 25 percent up to 5 years and 30 percent thereafter. Metal and other parts by vehicle age from first registration: nil to 6 months, 5 percent 6 months to 1 year, 10 percent 1 to 2 years, 15 percent 2 to 3 years, 25 percent 3 to 4 years, 35 percent 4 to 5 years, 40 percent 5 to 10 years, 50 percent above 10 years. Betterment, meaning the increase in value from fitting a new part in place of an old one, is borne by the insured through this depreciation and is not separately payable even under this comprehensive product.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'D-3', 'DEFINITION', 'Third-party liability and who is a third party', 'Third-party liability is the insured''s statutory liability under the Motor Vehicles Act 1988 for death or bodily injury to, and damage to property of, any person who is neither the insured nor the driver and is not being carried in or on the insured vehicle at the time. Pedestrians, cyclists, occupants of other vehicles and owners of other damaged property are third parties. The insured''s spouse, paid driver, occupants of the insured car, and the owner of goods carried in the insured car are not third parties under cover THIRD_PARTY. Death and injury awards are indemnified as fixed by Indian courts or Tribunals; property damage is capped per clause S-2.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'OWN_DAMAGE', 'S-1', 'SUB_LIMIT', 'Own Damage aggregate limit INR 800,000', 'The maximum payable under Own Damage in one policy period is INR 800,000 in aggregate including parts after depreciation per clause D-2, labour, towing up to INR 5,000 per event and survey fee. Compulsory excess per event applies within this limit. Amounts above INR 800,000 in a period are borne by the insured even if IDV is higher; IDV continues to cap any single total-loss or theft settlement within the unexhausted balance.', NULL, 800000.00, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'THIRD_PARTY', 'S-2', 'SUB_LIMIT', 'Third-party property damage limit INR 750,000', 'The maximum payable for third-party property damage under cover THIRD_PARTY is INR 750,000 per policy period in aggregate, covering assessed third-party repair cost, third-party towing and awarded claimant costs. No compulsory excess applies. Third-party death and bodily injury liability is not capped by this sub-limit and follows the award of a competent Indian court or Motor Accident Claims Tribunal. Costs of defending a Tribunal case with insurer consent are paid in addition to this sub-limit.', NULL, 750000.00, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'E-1', 'EXCLUSION', 'Drink-and-drive and drug-use exclusion', 'No claim under any cover is payable where the driver was under the influence of alcohol above 30 mg per 100 ml of blood or any narcotic or psychotropic drug at the time of accident, proved by breath, blood or urine analysis, casualty or medico-legal papers, or a charge under Section 185 of the Motor Vehicles Act 1988. Refusal to give a lawfully demanded sample is treated as breach of this clause. This applies even where the accident was partly caused by a third party.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'E-2', 'EXCLUSION', 'No effective driving licence exclusion', 'No claim under any cover is payable where the driver held no effective licence for the class of vehicle on the date of loss, including an expired licence beyond 30 days, a suspended licence, or a licence for a different class. A learner''s licence is effective only with L plates front and rear and a companion with an effective licence of that class for at least 3 years in the front seat. A licence that was valid but misplaced satisfies this clause if a duplicate or extract is produced within 15 days of demand.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'E-3', 'EXCLUSION', 'Hire, racing, testing and overloading exclusion', 'No claim under any cover is payable while the vehicle was used for hire or reward without commercial endorsement, for racing, pace-making, speed testing, reliability trials, rallies or practice, or while loaded beyond the registered laden weight or carrying passengers beyond the RC seating capacity. Overloading is judged from the RC entries and the surveyor''s report, for example 8 persons in a 5-seater at the time of loss. Private commuting and non-profit fuel sharing are not hire.', NULL, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'OWN_DAMAGE', 'O-1', 'EXCLUSION', 'Consequential engine and gearbox loss after water ingression', 'Own Damage covers only the direct effect of an insured peril on the engine and gearbox. Where flood or rain water has entered the engine, any connecting-rod bend, piston crack, crankcase damage or gearbox seizure caused by cranking, bump-starting or driving on after a stall is excluded as consequential hydrostatic and oil-starvation damage. The line is drawn at the stall point: draining, flushing and parts already damaged on first ingress, supported by the surveyor''s initial inspection, are payable; a full engine rebuild after a restart attempt, often INR 60,000 to INR 250,000, is not. This comprehensive product has no zero-depreciation add-on, so depreciation per clause D-2 still applies to admitted parts.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'OWN_DAMAGE', 'O-2', 'EXCLUSION', 'Wear and tear, breakdown and gradual failure', 'Own Damage excludes wear and tear, rust, gradual deterioration, and mechanical, electrical or electronic breakdown or failure not caused by an insured accident in the same event, including clutch wear, suspension bush wear, turbocharger fatigue and infotainment failure through ageing. A breakdown that itself causes an accident is still excluded for the failed part; only the resulting collision damage to other insured parts is payable. Depreciation computed under clause D-2 is excluded from every payment.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'OWN_DAMAGE', 'O-3', 'EXCLUSION', 'War, nuclear, requisition and territorial exclusion', 'Own Damage excludes loss caused by war, invasion, act of foreign enemy, hostilities, civil war, mutiny, rebellion, revolution, military or usurped power, ionising radiation or nuclear contamination, and requisition, seizure or destruction under government order. It also excludes any accident outside India, including Nepal and Bhutan; transit by rail, road or inland waterway between Indian points while carried as cargo remains covered. Riot, strike, malicious act, flood, cyclone and landslide inside India remain covered perils.', NULL, NULL, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'OWN_DAMAGE', 'O-4', 'EXCLUSION', 'Keys-in-vehicle theft and fraudulent disposal', 'Own Damage does not cover theft or pilferage where the vehicle was left unattended in a public place with keys in the ignition or doors unlocked, or where any insured, family member or authorised user was complicit in the taking. Entrustment of the vehicle to an unlicensed repairer or valet without a job card and identification entry is treated as unattended for this clause. Genuine forcible theft with broken locks or glass, supported by an FIR within 24 hours and the final untraced report, remains covered subject to clause C-2.', NULL, NULL, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'THIRD_PARTY', 'T-1', 'EXCLUSION', 'Injury to occupants and damage to insured property', 'Cover THIRD_PARTY does not indemnify death or injury of the insured, the driver, or any person carried in or on the insured vehicle including family and guests, nor damage to the insured vehicle itself, to property owned by or in the custody of the insured, or to goods carried in the insured vehicle. Occupant claims belong to personal accident or occupant covers where purchased. Only liability to persons and property genuinely outside the insured vehicle qualifies.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'THIRD_PARTY', 'T-2', 'EXCLUSION', 'Contractual liability, fines and punitive awards', 'Cover THIRD_PARTY indemnifies only statutory liability under the Motor Vehicles Act 1988. Liability assumed under any contract beyond the statute, fines, penalties and compounding amounts under the Act, and exemplary or punitive damages, are excluded. Interest on a Tribunal award is payable from filing to payment within limits, except interest attributable to the insured''s delay in forwarding summons beyond 7 days, which is borne by the insured.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', 'THIRD_PARTY', 'T-3', 'EXCLUSION', 'Foreign jurisdiction and deliberate act', 'Cover THIRD_PARTY responds only to awards of Indian courts and Motor Accident Claims Tribunals under the Motor Vehicles Act 1988 for accidents in India. Judgments of foreign courts and settlements under foreign law are excluded. Liability for death, injury or damage caused by a deliberate criminal act of the insured or driver, such as assault with the vehicle, is excluded; rash or negligent driving, even if prosecuted under Section 279 or 304A of the Indian Penal Code, is not deliberate for this clause and remains covered.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'C-1', 'CONDITION', 'Notice, police report and defence cooperation', 'Written notice of any accident, theft or third-party demand must reach the insurer within 48 hours with claim form, photographs and spot details within 7 days. Third-party injury, death, theft and riot events must be reported to police within 24 hours under Section 134 of the Motor Vehicles Act 1988. The insured must forward summons within 7 days, attend hearings when required, and must not admit liability or settle without written consent. The insurer may take over the defence in the insured''s name; non-cooperation allows recovery of wasted costs from the insured.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'C-2', 'CONDITION', 'Documents: RC, licence, FIR, bills and Tribunal papers', 'Own Damage claims require the RC with valid hypothecation entries, effective driving licence, estimate and final bills with parts-labour split, and salvage inspection. Theft requires both keys, FIR within 24 hours, final untraced report and transfer deeds. Third-party claims require FIR, charge sheet where issued, licence, policy copy, medical or post-mortem papers for injury, and Tribunal summons with all annexures. All papers must be filed within 30 days of demand after two reminders, failing which the file may be closed as no-claim and reopened once within 90 days on cause shown.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('AUTO-COM', NULL, 'C-3', 'CONDITION', 'Cashless network, survey discipline and salvage', 'Cashless repair is available only at authorised network garages on pre-authorisation against a surveyed estimate, and covers only insured parts less depreciation, consumables limits and excess. Repairs started before spot or final survey without consent are reimbursed only to the surveyor''s assessed reasonable cost for that city, and betterment is never cashless. Damaged parts must be retained for verification. On total loss, constructive total loss or theft payment, salvage vests in the insurer and the insured must deliver the wreck or recovered vehicle with keys, RC transfer forms and hypothecatee consent within 15 days of payment.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '1.1', 'EXCLUSION', 'War, nuclear contamination and wilful act', 'This policy does not cover loss or damage directly or indirectly caused by war, invasion, act of foreign enemy, hostilities, civil war, rebellion, insurrection, terrorism-related confiscation, or ionising radiation or nuclear contamination, or by the wilful or criminal act of the insured or any occupant acting with the insured''s consent. The burden of proving that a loss is not excluded under this clause lies on the insured.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '1.2', 'EXCLUSION', 'Wear and tear and gradual deterioration', 'This policy does not cover loss or damage caused by gradual deterioration, wear and tear, rust, corrosion, dampness, dry or wet rot, fungus, vermin, insects, or inherent vice. Only sudden and unforeseen physical damage caused by an insured peril such as fire, flood, storm or earthquake is payable; the cost of remedying the gradual cause itself is never payable.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '1.3', 'EXCLUSION', 'Pre-existing and unrepaired damage', 'No claim is payable for any crack, seepage, settlement or damage that existed before the policy start date, or for aggravation of unrepaired damage arising from an earlier event unless repairs were completed, photographed and disclosed to the insurer before inception. A claim must show fresh accidental damage occurring during the policy period.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '1.4', 'EXCLUSION', 'Prolonged unoccupancy limitation', 'If the dwelling at the registered address is continuously unoccupied for more than 60 days, loss by burglary, theft, water-tank overflow or malicious acts occurring after day 60 is excluded unless the insurer gave prior written consent with agreed unoccupancy conditions. Fire, lightning, flood, storm and earthquake cover continues during unoccupancy.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'STRUCTURE', '2.1', 'EXCLUSION', 'Outbuildings, boundary walls and external fixtures', 'Loss to outbuildings, garages used for commercial purposes, boundary and compound walls, gates, fences, swimming pools, decks, solar structures and external fixtures is excluded unless each such item is expressly listed with a sum insured in the policy schedule. Structure cover otherwise applies only to the main dwelling building described at the registered address in India.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'STRUCTURE', '2.2', 'EXCLUSION', 'Faulty design, construction and subsidence', 'Loss, damage or cracking to the structure caused by faulty design, defective construction or workmanship, use of substandard materials, or settlement, shrinkage, subsidence, landslide not caused by earthquake or flood, or soil heave is excluded. If an insured peril such as fire supervenes on such a defect, only the additional damage caused by the fire is payable.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'STRUCTURE', '2.3', 'EXCLUSION', 'Storm-water ingress versus storm damage', 'Damage caused by rain or storm water entering through open doors or windows, or through defective roofs, unsealed joints or defective waterproofing without any storm-created opening, is excluded as ingress and not storm damage. Storm cover requires violent wind, cyclone or hail that first creates an opening or directly damages the building envelope; seepage claims must evidence such an opening with photographs.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'CONTENTS', '3.1', 'EXCLUSION', 'Cash, jewellery and valuables unless declared', 'Loss of cash and currency notes, jewellery, precious stones, bullion, works of art, antiques, securities and title documents is excluded from contents cover unless specifically declared and listed in the schedule with agreed values. Even when declared, cash in the dwelling exceeding INR 25,000 at any one time is excluded from every claim.', NULL, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'CONTENTS', '3.2', 'EXCLUSION', 'Contents in open and shared areas', 'Loss or damage to contents kept in the open, on balconies, verandahs, terraces, lawns, or in common passages and stilt parking is excluded for theft, burglary, storm and water perils. Contents cover applies only to household goods kept inside the enclosed dwelling at the registered address.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'CONTENTS', '3.3', 'EXCLUSION', 'Burglary requires forcible-entry evidence', 'Burglary or attempted burglary of contents is covered only where there is visible evidence of forcible and violent entry into or exit from the dwelling, such as broken locks, doors, windows or grilles. Mysterious disappearance, pilferage by domestic staff or guests without forcible entry, and theft without break-in are excluded; an FIR must be lodged within 48 hours of discovery.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'STRUCTURE', '4.1', 'SUB_LIMIT', 'Structure sum insured cap', 'The insurer''s liability for the Structure cover is limited to INR 15,00,000 in aggregate per policy period, inclusive of debris-removal up to 1% of the admissible structure claim. This cap applies after any average-clause reduction and is the maximum payable for all structure claims combined in the policy year.', NULL, 1500000.00, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', 'CONTENTS', '4.2', 'SUB_LIMIT', 'Contents sum insured cap', 'The insurer''s liability for the Contents cover is limited to INR 5,00,000 in aggregate per policy period. No single item of furniture, appliance or personal effect exceeding INR 50,000 is payable beyond that per-item ceiling within the aggregate cap unless specifically listed in the schedule.', NULL, 500000.00, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '5.1', 'CONDITION', 'Claim notification, FIR and documentation', 'The insured shall intimate any claim within 7 days of discovery, lodge an FIR within 48 hours for burglary, theft, riot or malicious damage, protect the property from further loss, and submit ownership proof, purchase invoices, photographs and a room-wise inventory with quantities and values within 30 days. Non-compliance entitles the insurer to reduce or deny the claim to the extent it was prejudiced.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '5.2', 'CONDITION', 'Underinsurance average clause and reinstatement basis', 'If the structure or contents are underinsured at the time of loss, the average clause applies and the payable amount is reduced in the proportion that the sum insured bears to the reinstatement value. Claims are settled on reinstatement (new-for-old, without depreciation) up to the sum insured where repairs or replacement are completed within 12 months of loss; otherwise settlement is on depreciated market value.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '5.3', 'CONDITION', 'Plinth, foundation and salvage treatment', 'The structure sum insured excludes the value of plinth and foundations unless expressly included in the schedule. Where included, only the cost of superstructure support needed to rebuild is payable; the cost of undamaged foundations is never payable and any technically reusable portion must be used. Salvage of damaged materials vests with the insurer on payment of a total-loss claim.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '6.1', 'DEFINITION', 'Structure versus contents boundary', 'Structure means the main dwelling building including walls, roof, floors, fixed plumbing, concealed electrical wiring, and permanently fitted kitchens and wardrobes fixed to the building fabric. Contents means household goods not forming part of the building; fitted kitchens are structure while freestanding or modular units removable without damage are contents. Doubtful items are decided by whether removal would damage the building fabric.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '6.2', 'DEFINITION', 'Market value versus reinstatement value', 'Market value means the depreciated replacement cost of the building or item of similar age, condition and construction at the time of loss. Reinstatement value means the cost of rebuilding or replacing as new, without deduction for depreciation, at the registered-address site or the nearest equivalent site. Underinsurance is measured against reinstatement value where the policy is on reinstatement basis.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('HOME', NULL, '6.3', 'DEFINITION', 'Fire and allied and special perils enumeration', 'Insured perils under this product comprise fire, lightning, explosion of domestic gas, and allied and special perils: flood and inundation, storm, cyclone, tempest, hurricane, tornado, subsidence and landslide including rockslide caused by flood or earthquake, earthquake including fire and shock, riot, strike and malicious damage, missile testing, leakage from automatic sprinklers, and burglary by forcible entry. Perils operate subject to the exclusions and conditions of this wording.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-1.1', 'EXCLUSION', 'War, nuclear risks and intentional acts', 'This policy excludes loss or damage occasioned directly or indirectly by war, invasion, hostilities, civil commotion amounting to a popular rising, or ionising radiation or radioactivity from nuclear fuel or waste, and any loss caused by the deliberate or fraudulent act of the insured, a family member or any person acting on their instructions. The insured must prove a claimed loss falls outside this exclusion.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-1.2', 'EXCLUSION', 'Gradual causes and maintenance failures', 'Loss arising from wear and tear, gradual operating causes, rust, oxidation, seepage developing over 14 or more days, defective maintenance, or the cost of routine servicing is excluded. Where an insured peril such as a burst pipe or fire follows a gradual cause, only the ensuing sudden damage is admissible and the cost of repairing the worn part itself is excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-1.3', 'EXCLUSION', 'Commercial use and structural alteration', 'Loss occurring while any portion of the registered dwelling is used for manufacturing, storage of hazardous goods, or commercial activity beyond home-office use, or while structural alteration, extension or demolition is in progress, is excluded unless the insurer endorsed the change beforehand. Ordinary repair and decoration not involving load-bearing work remain covered.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-1.4', 'EXCLUSION', 'Unoccupied dwelling and tenant risks', 'Burglary, theft, water-damage and malicious-damage claims arising after the dwelling has been continuously unoccupied for 45 days are excluded unless the insurer recorded extended-unoccupancy consent. Cover also excludes loss caused by a tenant''s or paying guest''s theft or collusion except by forcible break-in evidenced under clause P-3.3, for which an FIR naming the facts is mandatory.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'STRUCTURE', 'P-2.1', 'EXCLUSION', 'Boundary structures and appurtenant fittings', 'Compound and boundary walls, gates, fences, car porches not under the main roof, external sheds, television aerials, signage and garden landscaping are not covered as structure unless shown as separate schedule items with sums insured. Structure means the enclosed main residence at the registered address; a claim for a wall or gate must cite its schedule serial number.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'STRUCTURE', 'P-2.2', 'EXCLUSION', 'Defective construction and soil movement', 'Cracking, bulging or collapse attributable to defective design, faulty workmanship, under-designed foundations, or normal settlement and heave of made-up ground is excluded. Earthquake, flood-induced landslide and storm remain covered perils, but the insured must show the damage pattern is consistent with the insured event rather than with pre-existing movement, failing which the surveyor shall apportion accordingly.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'STRUCTURE', 'P-2.3', 'EXCLUSION', 'Flood versus storm-water ingress classification', 'Inundation by overflowing rivers, drains or accumulated rainwater entering at ground level is assessed as flood; water entering only through an unclosed skylight, ventilator or window, or through cracked waterproofing with no flood at the premises, is assessed as ingress and excluded. Where both occur together, only the flood-attributable portion proved by waterline marks and locality flooding evidence is payable.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'CONTENTS', 'P-3.1', 'EXCLUSION', 'Valuables, documents and business stocks', 'Bullion, unset gems, jewellery above INR 1,00,000 per household unless valued and endorsed, cash above INR 20,000, deeds, manuscripts and business stocks or samples are excluded from contents. Personal laptops up to two in number are covered as contents only while inside the dwelling; loss outside the registered address is never covered under this product.', NULL, NULL, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'CONTENTS', 'P-3.2', 'EXCLUSION', 'Contents outside the enclosed dwelling', 'Contents in corridors, staircases, terraces, open parking, or with third parties for repair or dry-cleaning are excluded except for fire and earthquake while temporarily removed up to 5% of the contents sum insured and for no longer than 15 days. Theft or water damage outside the enclosed dwelling is excluded in all cases.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'CONTENTS', 'P-3.3', 'EXCLUSION', 'Non-violent entry and insider pilferage', 'Contents loss is not payable as burglary where entry was obtained by key, access code or persuasion without visible violent force, or where the loss is gradual pilferage that cannot be tied to a dated break-in. The claim must produce photographs of the point of forced entry, a list of items with purchase proof, and an FIR registered within 48 hours; key-based entry by a former occupant within 30 days of a lock change is treated as forcible only with an FIR naming the person.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'STRUCTURE', 'P-4.1', 'SUB_LIMIT', 'Structure aggregate cap', 'The maximum payable under the Structure cover is INR 15,00,000 per policy period in aggregate, including architect and debris-removal charges capped at 3% of the net admissible structure loss. Reinstatement estimates beyond this cap are scaled down rateably across all structure heads of claim.', NULL, 1500000.00, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', 'CONTENTS', 'P-4.2', 'SUB_LIMIT', 'Contents aggregate cap', 'The maximum payable under the Contents cover is INR 5,00,000 per policy period in aggregate. Any one domestic appliance claim is capped at INR 75,000 within that aggregate unless the appliance is individually listed in the schedule with a higher agreed value.', NULL, 500000.00, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-5.1', 'CONDITION', 'Prompt intimation and loss mitigation', 'On discovering loss the insured must intimate the insurer within 7 days, inform the police and fire brigade where applicable, take reasonable steps to protect and preserve the property, and retain damaged parts for survey. The surveyor may deny the portion of loss aggravated by delay or by disposal of salvage before inspection.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-5.2', 'CONDITION', 'Ownership proof, inventory and average clause', 'Every claim must be supported within 30 days by proof of ownership, a room-wise inventory with age and value, and repair or replacement estimates on letterhead. Where the sum insured is below 85% of the reinstatement value, the average clause reduces the claim proportionately; deliberate overstatement of any head forfeits that head of claim.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-5.3', 'CONDITION', 'Reinstatement, indemnity option and foundation basis', 'Settlement is on reinstatement basis without depreciation if reinstatement starts within 6 months and finishes within 18 months at the same registered-address site; otherwise settlement is on indemnity (depreciated) basis at the insurer''s option. Plinth and foundations are deemed excluded from the sum insured unless added by endorsement, and undamaged foundations must be reused wherever the municipal authority permits.', NULL, NULL, NULL, '2020-01-01', NULL, 150);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-6.1', 'DEFINITION', 'Structure and contents dividing line', 'The structure comprises load-bearing and enclosing elements plus items immovably fixed with cement, welding or concealed fastening, including fitted kitchen carcasses and fixed bathroom sanitaryware. Contents comprise movable household goods including modular kitchen baskets, chimneys and freestanding white goods. A fitted-kitchen dispute is resolved by the removal test: if detachment without tools and without marring the finish is possible, the item is contents.', NULL, NULL, NULL, '2020-01-01', NULL, 160);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-6.2', 'DEFINITION', 'Reinstatement and market value of a home', 'Reinstatement value of the structure is the cost of reconstructing the same carpet area and specification as new at current municipal rates; of contents it is the price of new articles of like kind and quality. Market value deducts depreciation for age, wear and obsolescence at rates certified by the surveyor, subject to a minimum 10% per year on electronics and 5% per year on furniture.', NULL, NULL, NULL, '2020-01-01', NULL, 170);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-HOME', NULL, 'P-6.3', 'DEFINITION', 'Allied perils scope for a home policy', 'Allied and special perils mean flood and inundation, storm, cyclone, typhoon, tempest, hurricane, tornado, earthquake with fire and shock, subsidence and landslide including rockslide, bursting or overflowing of water tanks and pipes, missile-testing operations, riot, strike, malicious damage, and bush fire. Lightning, explosion of domestic cooking gas, and burglary with forcible entry are insured alongside fire, each subject to its stated exclusions.', NULL, NULL, NULL, '2020-01-01', NULL, 180);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-1.1', 'EXCLUSION', 'War, pollution and wilful burning', 'Loss by war, civil war, confiscation by public authority, nuclear reaction, or wilful burning by or at the direction of the insured or mortgagee is excluded from every section of this fire policy. Fire damage caused by the insured''s negligence remains covered, but arson, fraud or connivance voids the claim and the related cover for that premises.', NULL, NULL, NULL, '2020-01-01', NULL, 10);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-1.2', 'EXCLUSION', 'Consequential, electrical and gradual losses', 'Consequential loss of rent, profit or use, loss by delay or market fall, and the cost of repairing the electrical, mechanical or electronic defect itself (such as short-circuiting without ensuing fire) are excluded. Only fire, explosion or allied-peril damage ensuing from the defect to otherwise sound property is payable, plus fire-brigade damage reasonably incurred.', NULL, NULL, NULL, '2020-01-01', NULL, 20);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-1.3', 'EXCLUSION', 'Wear, fermentation and uninsured location', 'Loss by wear and tear, rust, gradual seepage, fermentation, natural heating or spontaneous combustion of stocks without outbreak of fire, and any loss at a location not named in the schedule as an insured premises, is excluded. Spontaneous combustion becomes a fire claim only from the point flames break out and spread to surrounding property.', NULL, NULL, NULL, '2020-01-01', NULL, 30);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-1.4', 'EXCLUSION', 'Hazardous storage and unoccupancy', 'Loss where the insured premises stored fireworks, explosives, or hazardous chemicals beyond the quantity declared and accepted in the proposal, or where the premises were continuously unoccupied for more than 30 days without insurer consent, is excluded for fire, burglary and water perils occurring during the breach. Earthquake and lightning cover persists but the claim is reduced by 25% for unoccupancy beyond 30 days.', NULL, NULL, NULL, '2020-01-01', NULL, 40);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', 'FIRE', 'F-2.1', 'EXCLUSION', 'Burning by public authority and controlled fire', 'Destruction by order of a public authority to prevent spread of fire, and damage from controlled domestic or agricultural burning that escapes, is excluded to the extent it affects only the property deliberately exposed. Ensuing accidental fire to neighbouring insured property caught unintentionally is covered as fire, with apportionment recorded by the surveyor.', NULL, NULL, NULL, '2020-01-01', NULL, 50);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', 'FIRE', 'F-2.2', 'EXCLUSION', 'Stocks in open and explosion of boilers', 'Fire and allied-peril loss to stocks or contents stored in the open, under tarpaulin or in temporary sheds, and loss from explosion of boilers, economisers or pressure vessels in the insured''s custody, is excluded unless specifically endorsed with additional premium. Explosion of domestic cooking gas and lightning-caused fire remain covered under the FIRE cover.', NULL, NULL, NULL, '2020-01-01', NULL, 60);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', 'FIRE', 'F-2.3', 'EXCLUSION', 'Theft during fire and flood classification', 'Theft, burglary or mysterious disappearance during or after a fire is covered only with visible forcible-entry or fire-service corroboration and an FIR within 48 hours; unattributed shortages found at stock-taking are excluded. Flood under this cover means external inundation from rivers, drains or storm accumulation; internal flooding from burst pipes is assessed under the bursting-pipes peril and not as flood, and ingress through defective waterproofing alone is excluded.', NULL, NULL, NULL, '2020-01-01', NULL, 70);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', 'FIRE', 'F-3.1', 'SUB_LIMIT', 'Fire and allied perils aggregate cap', 'The insurer''s liability under the Fire and Allied Perils cover is limited to INR 20,00,000 in aggregate per policy period for building, contents and stocks combined, including fire-brigade, protection and debris-removal charges capped at 5% of the net admissible loss. Average clause applies within this cap where any insured item is underinsured.', NULL, 2000000.00, NULL, '2020-01-01', NULL, 80);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-4.1', 'CONDITION', 'Fire intimation, records and survey', 'Every fire, explosion or allied-peril occurrence must be intimated within 7 days, the fire brigade report and FIR where required obtained within 15 days, and stock registers, building plans, invoices and books of account preserved and produced. Failure to produce verifiable stock and purchase records limits the stocks claim to 75% of the estimated loss assessed by the surveyor.', NULL, NULL, NULL, '2020-01-01', NULL, 90);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-4.2', 'CONDITION', 'Average clause and reinstatement option', 'Where the declared value is below the reinstatement value of the building or stocks, the claim is scaled down proportionately under the average clause. Buildings may be reinstated new-for-old if reconstruction begins within 6 months and completes within 18 months at the same Indian site; stocks are always settled on market value at the place of loss on the date of fire, never on selling price.', NULL, NULL, NULL, '2020-01-01', NULL, 100);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-4.3', 'CONDITION', 'Registered-address scope and foundation basis', 'Cover applies only to the building, contents and stocks at the registered address stated in the schedule; property temporarily removed for repair is covered up to 5% of the sum insured for fire only. Plinth and foundation values are excluded from the building sum insured unless endorsed; undamaged foundations must be reused and only shoring and superstructure costs are payable.', NULL, NULL, NULL, '2020-01-01', NULL, 110);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-5.1', 'DEFINITION', 'Building, contents and stocks boundary', 'Building means the insured structure including walls, roof, flooring and fixed services but excluding land, plinth and foundations unless endorsed. Contents means household or office furniture and fittings; stocks means raw, finished or trade goods held for sale. Fitted kitchen carcasses fixed with cement or concealed fasteners are building; modular shelves and appliances removable without damage are contents and never stocks.', NULL, NULL, NULL, '2020-01-01', NULL, 120);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-5.2', 'DEFINITION', 'Market value and reinstatement for fire cover', 'Market value is the depreciated cost of repairing or replacing the building, or the landed cost of equivalent stocks on the date of loss. Reinstatement value is the new-for-old reconstruction or replacement cost at the same site without depreciation. Depreciation on buildings is assessed by age, construction and maintenance; stocks carry no depreciation but carry average clause on declared versus actual insurable value.', NULL, NULL, NULL, '2020-01-01', NULL, 130);
INSERT INTO policy_clause (product_code, cover_code, clause_ref, clause_type, title, clause_text, waiting_period_days, sub_limit_amount, co_pay_percent, effective_from, effective_to, sort_order) VALUES ('PROP-FIRE', NULL, 'F-5.3', 'DEFINITION', 'Fire and allied perils enumeration', 'Fire means actual ignition with flame outside its normal confines, including lightning and explosion of domestic gas. Allied and special perils mean flood and inundation, storm, cyclone, tempest, tornado, earthquake with fire and shock, subsidence and landslide including rockslide, bursting of water tanks and pipes, riot, strike, malicious and terrorist damage, missile testing, sprinkler leakage and bush fire, each subject to the exclusions above and the schedule endorsements.', NULL, NULL, NULL, '2020-01-01', NULL, 140);
